CREATE TABLE IF NOT EXISTS questions (id TEXT PRIMARY KEY, grade INTEGER NOT NULL, unit INTEGER NOT NULL, domain TEXT NOT NULL, type TEXT NOT NULL, prompt TEXT NOT NULL, choices TEXT NOT NULL DEFAULT '[]', answer TEXT NOT NULL DEFAULT '', points INTEGER NOT NULL DEFAULT 5, media TEXT NOT NULL DEFAULT '{}', ready INTEGER NOT NULL DEFAULT 0, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS exams (id TEXT PRIMARY KEY, title TEXT NOT NULL, grade INTEGER NOT NULL, unit INTEGER NOT NULL, duration INTEGER NOT NULL DEFAULT 40, result_policy TEXT NOT NULL DEFAULT 'teacher', status TEXT NOT NULL DEFAULT 'draft', created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS exam_questions (exam_id TEXT NOT NULL, question_id TEXT NOT NULL, seq INTEGER NOT NULL, snapshot TEXT NOT NULL, PRIMARY KEY(exam_id,question_id));
CREATE TABLE IF NOT EXISTS students (id TEXT PRIMARY KEY, grade INTEGER NOT NULL, class_no INTEGER NOT NULL, student_no INTEGER NOT NULL, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS enrollments (id TEXT PRIMARY KEY, exam_id TEXT NOT NULL, student_id TEXT NOT NULL, code_hash TEXT NOT NULL UNIQUE, revoked INTEGER NOT NULL DEFAULT 0, UNIQUE(exam_id,student_id));
CREATE TABLE IF NOT EXISTS attempts (id TEXT PRIMARY KEY, enrollment_id TEXT NOT NULL UNIQUE, token_hash TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active', started_at INTEGER NOT NULL, deadline_at INTEGER NOT NULL, submitted_at INTEGER, score REAL);
CREATE TABLE IF NOT EXISTS responses (attempt_id TEXT NOT NULL, question_id TEXT NOT NULL, answer TEXT NOT NULL, saved_at INTEGER NOT NULL, PRIMARY KEY(attempt_id,question_id));
CREATE TABLE IF NOT EXISTS media (id TEXT PRIMARY KEY, key TEXT NOT NULL, mime TEXT NOT NULL, name TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_exam_questions ON exam_questions(exam_id,seq);
CREATE INDEX IF NOT EXISTS idx_attempt_enrollment ON attempts(enrollment_id);
